  cx.flush();
  calls.length = 0;
  const key = v.turnKeys(v.rows()).at(-3);
  v.toggle(key, cx);
  // The scroll waits while the card's parts are still to be measured (issue 131)...
  expect(v.probeDue().length).toBeGreaterThan(0);
  v.render(cx);
  cx.flush();
  expect(calls).toEqual([]);
  expect(v.scrollTo).toMatchObject({ key, how: "card" });
  // ...and runs once they are.
  v.probeDue = () => [];
  v.render(cx);
  cx.flush();
  const rows = v.rows();
  const head = rows.findIndex((r) => r.key === key);
  let last = head;
  while (last + 1 < rows.length && rows[last + 1].kind !== "head" && rows[last + 1].kind !== "turn" && rows[last + 1].kind !== "spacer" && rows[last + 1].kind !== "wrow") last++;
  expect(rows[head].kind).toBe("head");
