  expect(md.shape.mdBase).toBe(8 + 12 + md.shape.p * 22 + 6 + 16 + 6 + 24 + 6 + 6 + 16 + 10 + 18 * ((md.shape.pMore ? 1 : 0) + (md.shape.rMore ? 1 : 0)));
