  expect(hasId(c, "th-traj-detail")).toBe(true);
  const L = v.ledger();
  expect(L.totals.failed).toBeGreaterThan(0);
  // f: to the first failed call after the selected row; the heading says which of them.
  v.tsel = L.rows.find((r) => r.kind === "trh").key;
